class Solution:
    def afterCollisions(self, comets: List[int]) -> List[int]:
        a = list(comets)
        i = 0
        while i < len(a) - 1:
            if a[i] > 0 and a[i + 1] < 0:
                if a[i] > -a[i + 1]:
                    del a[i + 1]
                elif a[i] < -a[i + 1]:
                    del a[i]
                else:
                    del a[i:i + 2]
                i = 0
            else:
                i += 1
        return a

