class Solution {
    public int[] afterCollisions(int[] comets) {
        List<Integer> a = new ArrayList<>();
        for (int c : comets) a.add(c);
        int i = 0;
        while (i < a.size() - 1) {
            int x = a.get(i), y = a.get(i + 1);
            if (x > 0 && y < 0) {
                if (x > -y) a.remove(i + 1);
                else if (x < -y) a.remove(i);
                else { a.remove(i + 1); a.remove(i); }
                i = 0;
            } else i++;
        }
        int[] out = new int[a.size()];
        for (int k = 0; k < out.length; k++) out[k] = a.get(k);
        return out;
    }
}

