class Solution {
public:
    vector<int> afterCollisions(vector<int>& comets) {
        vector<int> a = comets;
        size_t i = 0;
        while (i + 1 < a.size()) {
            if (a[i] > 0 && a[i + 1] < 0) {
                if (a[i] > -a[i + 1]) a.erase(a.begin() + i + 1);
                else if (a[i] < -a[i + 1]) a.erase(a.begin() + i);
                else a.erase(a.begin() + i, a.begin() + i + 2);
                i = 0;
            } else i++;
        }
        return a;
    }
};

