static void removeAt(int* a, int* n, int i, int count) {
    for (int k = i; k + count < *n; k++) a[k] = a[k + count];
    *n -= count;
}

int* afterCollisions(int* comets, int cometsSize, int* returnSize) {
    int* a = malloc(cometsSize * sizeof(int));
    memcpy(a, comets, cometsSize * sizeof(int));
    int n = cometsSize, i = 0;
    while (i < n - 1) {
        if (a[i] > 0 && a[i + 1] < 0) {
            if (a[i] > -a[i + 1]) removeAt(a, &n, i + 1, 1);
            else if (a[i] < -a[i + 1]) removeAt(a, &n, i, 1);
            else removeAt(a, &n, i, 2);
            i = 0;
        } else i++;
    }
    *returnSize = n;
    return a;
}

