class Solution {
    public int[] afterCollisions(int[] comets) {
        int[] stack = new int[comets.length];
        int top = 0;
        for (int c : comets) {
            boolean alive = true;
            while (alive && c < 0 && top > 0 && stack[top - 1] > 0) {
                if (stack[top - 1] < -c) top--;
                else if (stack[top - 1] == -c) { top--; alive = false; }
                else alive = false;
            }
            if (alive) stack[top++] = c;
        }
        return Arrays.copyOf(stack, top);
    }
}

