    vector<int> afterCollisions(vector<int>& comets) {
        vector<int> stack;
        for (int c : comets) {
            bool alive = true;
            while (alive && c < 0 && !stack.empty() && stack.back() > 0) {
                if (stack.back() < -c) stack.pop_back();
                else if (stack.back() == -c) { stack.pop_back(); alive = false; }
                else alive = false;
            }
            if (alive) stack.push_back(c);
        }
        return stack;
    }
};

